    "Tipo de arquivo não aceito.": ["File type not accepted.", "Tipo de archivo no aceptado."], "Use o formato MM/AA.": ["Use the MM/YY format.", "Usa el formato MM/AA."], "Veículo trocado. Revalide os condutores.": ["Vehicle swapped. Revalidate the drivers.", "Vehículo cambiado. Revalida los conductores."], "Você precisa aceitar os termos, o preço e a política de cancelamento para continuar.": ["You must accept the terms, the price and the cancellation policy to continue.", "Debes aceptar los términos, el precio y la política de cancelación para continuar."],
    "Escolha um assunto.": ["Choose a topic.", "Elige un tema."], "Conta criada": ["Account created", "Cuenta creada"], "Documento enviado. Status: aguardando conferência.": ["Document sent. Status: awaiting check.", "Documento enviado. Estado: esperando verificación."], "CNH enviada. Aguardando conferência.": ["License sent. Awaiting check.", "Licencia enviada. Esperando verificación."], "Selecione": ["Select", "Selecciona"],
